/* Case narratives are adapted from Sherry's supplied portfolio. */
const para = text => `<p>${text}</p>`;
const cards = rows => `<div class="story-cards">${rows.map(([title,text],i)=>`<article><span class="card-seq">0${i+1}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div>`;
const quote = (text,caption='') => `<blockquote class="story-quote">${text}${caption?`<cite>${caption}</cite>`:''}</blockquote>`;
const artwork = (src,alt,caption,cls='') => `<figure class="artwork ${cls}"><button class="zoom-art" data-zoom="assets/${src}.webp" aria-label="放大查看${alt}"><img src="assets/${src}.webp" alt="${alt}" loading="lazy"><span>放大查看 ↗</span></button><figcaption>${caption}</figcaption></figure>`;
const gallery = items => `<div class="art-grid">${items.map(a=>artwork(...a)).join('')}</div>`;
const facts = rows => `<dl class="fact-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
const scene = (n,head,body,seconds,sound) => `<article class="scene"><span class="scene-id">SHOT ${String(n).padStart(2,'0')} <b>${seconds}</b></span><h3>${head}</h3><p>${body}</p><small>声音 / ${sound}</small></article>`;
const section = (label,title,body,kind='') => ({label,title,body,kind});
const filmPlayer = (key,title,duration,portrait=false) => `<figure class="film-player ${portrait?'portrait-player':''}"><div class="video-frame"><video controls playsinline preload="none" poster="assets/${key}-poster.webp" aria-label="${title}"><source src="assets/video/${key}.mp4" type="video/mp4">你的浏览器暂不支持视频播放。<a href="assets/video/${key}.mp4">打开影片</a></video><button class="video-activate" aria-label="播放${title}"><span aria-hidden="true">▶</span></button></div><figcaption><span>${title}</span><small>${duration} / 完整影片</small></figcaption></figure>`;
const originalWork = (url,title,platform='微信原文') => `<a class="published-work" href="${url}" target="_blank" rel="noopener noreferrer"><span><small>${platform}</small><strong>${title}</strong></span><b aria-hidden="true">↗</b></a>`;
